M2C_UNK stopSound(s32);                         /* extern */
extern s32 sCurrentDistanceSoundId;
extern s32 sDistanceSoundResult;

/* Stops the active distance sound (if any) and clears the current sound ids. */ void stopDistanceSound(void) {
    s32 *resultPtr;
int noSound = -1;

    resultPtr = &sDistanceSoundResult;
    if ((*resultPtr) != -1) {
        stopSound((*resultPtr));
        (*resultPtr) = noSound;
resultPtr = 0;
    }
    sCurrentDistanceSoundId = noSound;
}
